/*updateBuyerWmGrWarehousingSolbLisGrdt*/
UPDATE ICOMGRDT A
SET 
	  A.STATUS         = 'D'
	, A.SEND_DATE      = ' '
	, A.SEND_TIME      = ' '
	, A.CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
	, A.CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
	, A.CHANGE_USER_ID = #{user_id}
WHERE
		A.BUYER   = #{com_code}
	AND A.GR_NO   = #{gr_no}
	AND A.GR_SEQ  = #{gr_seq}


/*updateBuyerWmGrWarehousingSolbLisIvdt*/
UPDATE ICOMIVDT A
SET
	A.GR_QTY = DECODE((	SELECT B.PROCESS_TYPE 
						FROM ICOMGRDT B
						WHERE 	B.BUYER = #{com_code}
							AND B.GR_NO = #{gr_no}
							AND B.GR_SEQ = #{gr_seq}
				),'0', 0 , 'G1', 0, A.GR_QTY)
WHERE
		A.BUYER 	= #{com_code}
	AND (A.INV_NO, A.INV_SEQ) IN
	 (SELECT GR.INV_NO, GR.INV_SEQ FROM ICOMGRDT GR WHERE A.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})
	AND A.STATUS	<>'D'


/*updateBuyerWmGrWarehousingSolbLisIvhd*/
UPDATE ICOMIVHD IV
SET IV.GR_DATE = ''
WHERE 
		IV.BUYER   = #{com_code}
	AND IV.INV_NO  = (SELECT GR.INV_NO FROM ICOMGRDT GR WHERE IV.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})


/*updateBuyerWmGrWarehousingSolbRefNoGrdt*/
UPDATE ICOMGRDT A
SET 
	  A.REF_PR_NO = #{ref_no}
WHERE
		A.BUYER   = #{com_code}
	AND A.GR_NO   = #{gr_no}
	AND A.GR_SEQ  = #{gr_seq}


/*updateBuyerWmGrWarehousingSolbRefNoPodt*/
UPDATE ICOMPODT PO
SET 
	PO.REF_PR_NO = #{ref_no}
WHERE 
		PO.BUYER   = #{com_code}
	AND (PO.PO_NO, PO.PO_SEQ) IN
	 (SELECT GR.PO_NO, GR.PO_SEQ FROM ICOMGRDT GR WHERE PO.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})


/*updateBuyerWmGrWarehousingSolbRefNoIvdt*/
UPDATE ICOMIVDT A
SET
	A.REF_PR_NO = #{ref_no}
WHERE
		A.BUYER 	= #{com_code}
	AND (A.INV_NO, A.INV_SEQ) IN
	 (SELECT GR.INV_NO, GR.INV_SEQ FROM ICOMGRDT GR WHERE A.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})
	AND A.STATUS	<>'D'


/*updateBuyerWmGrWarehousingSolbRefNoWmsIvdt1*/
UPDATE WMSIVDT A 
SET
	  A.REF_PR_NO = #{ref_no}
WHERE 
		A.BUYER  = #{com_code}
	AND A.WAREHOUSE_CODE = #{warehouse_code}
	AND A.SELLER   = 'KRKORE0001'
	AND (A.PO_NO, A.PO_SEQ) IN
	(SELECT GR.PO_NO, GR.PO_SEQ FROM ICOMGRDT GR WHERE A.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})
	AND A.STATUS  != 'D'


/*updateBuyerWmGrWarehousingSolbRefNoWmsIvdt2*/
UPDATE WMSIVDT A 
SET
	  A.REF_PR_NO = #{ref_no}
WHERE 
	A.BUYER  = #{com_code}
AND A.WAREHOUSE_CODE = #{warehouse_code}
AND A.SELLER   = 'KRKORE0001'
AND (A.INV_NO, A.INV_SEQ) IN
	(SELECT GR.INV_NO, GR.INV_SEQ FROM ICOMGRDT GR WHERE A.BUYER = GR.BUYER AND GR.GR_NO = #{gr_no} AND GR.GR_SEQ = #{gr_seq})
AND A.STATUS  != 'D'


